  return styledStereotypesOf(names).map((name) =>
    '<span class="stereotype-badge" style="' + escapeHtml(styleVarsText(stereotypeBadgeVarsOf(name))) + '" title="Stereotype: ' + escapeHtml(name) + '">' + escapeHtml(name) + '</span>').join('');
